test("settle as of date scenario 3", { tag: '@functionality' }, async ({ browser }) => {
  const sheet = ui.sheetId();
  const pg_uma = await ui.userPage(browser, "uma", sheet);
  await ui.setToday(pg_uma, "2026-04-05");
  expect(await ui.setRole(pg_uma, "wes", "steward")).toBe(true);
  await ui.setSetting(pg_uma, "floor", "2.00");
  await ui.setSetting(pg_uma, "terms", "30");
  await ui.setSetting(pg_uma, "late-pct", "5.00");
  await ui.setSetting(pg_uma, "period-numbering-from", "2026-03-01");
  await ui.setSetting(pg_uma, "terms-A", "20");
  await ui.setSetting(pg_uma, "perm-void", "steward");
  expect(await ui.setRole(pg_uma, "vic", "viewer")).toBe(true);
  await ui.setSetting(pg_uma, "grace-C", "5");
  expect(await ui.saveTemplate(pg_uma, {"name": "T1", "amount": "0.04", "note": ""})).toBe(true);
  await ui.setSetting(pg_uma, "pot", "7.77");
  await ui.setSetting(pg_uma, "alert-threshold", "1.00");
  expect(await ui.setSettingDated(pg_uma, "rounding", "half-even", "2026-03-01", "half-even")).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "7.50"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "20.00"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "C", "pct": "33.33"})).toBe(true);
  expect(await ui.addPeriod(pg_uma, {"name": "P1", "from": "2026-03-01", "to": "2026-03-15"})).toBe(true);
  const p_ada = ui.must(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "C", "contact": " Ada@x ", "tags": "b, a"}));
  const p_ben = ui.must(await ui.addPerson(pg_uma, {"name": "Ben", "grade": "A", "contact": "ben@x"}));
  expect(await ui.addCrew(pg_uma, "C1", "Ada")).toBe(true);
  const pl_ben_1 = ui.must(await ui.addPlan(pg_uma, p_ben, {"amount": "12.50", "start": "2026-02-20", "end": "2026-04-30", "every": "10"}));
  expect(await ui.statement(pg_uma, p_ada)).toBe(true);
  expect(await ui.statement(pg_uma, p_ada)).toBe(true);
  expect(await ui.generatePlans(pg_uma)).toBe(5);
  const c_ben_0 = await ui.claimAt(pg_uma, p_ben, 0);
  const c_ben_1 = await ui.claimAt(pg_uma, p_ben, 1);
  const c_ben_2 = await ui.claimAt(pg_uma, p_ben, 2);
  const c_ben_3 = await ui.claimAt(pg_uma, p_ben, 3);
  const c_ben_4 = await ui.claimAt(pg_uma, p_ben, 4);
  expect(await ui.claimAction(pg_uma, c_ben_2, "open")).toBe(true);
  const pg_wes = await ui.userPage(browser, "wes", sheet);
  expect(await ui.delegate(pg_wes, {"user": "uma", "from": "2026-03-15", "to": "2026-04-02"})).toBe(true);
  await ui.refresh(pg_uma);
  await ui.refresh(pg_wes);
  expect(await ui.unstate(pg_wes, p_ada)).toBe(true);
  expect(await ui.claimAction(pg_wes, c_ben_2, "settle", "2026-02-10")).toBe(false);
  await ui.refresh(pg_wes);
  await expect(pg_wes.getByTestId("person-row-" + p_ada).getByTestId("person-claimed")).toHaveText("0.00");
  await expect(pg_wes.getByTestId("person-row-" + p_ada).getByTestId("person-due-total")).toHaveText("0.00");
  await expect(pg_wes.getByTestId("person-row-" + p_ben).getByTestId("person-claimed")).toHaveText("12.50");
  await expect(pg_wes.getByTestId("person-row-" + p_ben).getByTestId("person-due-total")).toHaveText("1.00");
  await expect(pg_wes.getByTestId("claim-row-" + c_ben_4).getByTestId("claim-due")).toHaveText("1.00");

