package net.officefloor.hq.app.setting;

import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;
import java.net.URLDecoder;
import java.nio.charset.StandardCharsets;
import java.util.Map;
import java.util.Set;
import net.officefloor.hq.app.SignedInUser;
import org.springframework.http.HttpMethod;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Component;
import org.springframework.util.AntPathMatcher;
import org.springframework.web.servlet.HandlerInterceptor;

/**
 * A viewer sees every screen and figure and can change nothing: every request that would change a
 * sheet is refused (403) before it reaches its controller, so it writes nothing to the store or the
 * audit. Loading a sheet changes nothing and is let through; so are the bulk actions, which a
 * viewer takes with nothing done (every selected item refused, see the bulk services), and the
 * plans' generate, which makes nothing for a viewer (see the plan service).
 */
@Component
public class ViewerGuard implements HandlerInterceptor {

    /** The sheet-scoped requests the guard watches. */
    public static final String PATTERN = "/api/sheets/{sheetId}/**";

    /** The requests a viewer may make: loading a sheet, the bulk actions that refuse every item, and
     *  generating plans' claims, which makes none for a viewer. */
    private static final Set<String> LET_THROUGH = Set.of(
            "/api/sheets/{sheetId}/load",
            "/api/sheets/{sheetId}/claims/open",
            "/api/sheets/{sheetId}/claims/settle",
            "/api/sheets/{sheetId}/claims/reassign",
            "/api/sheets/{sheetId}/people/grade",
            "/api/sheets/{sheetId}/people/retire",
            "/api/sheets/{sheetId}/plans/generate");

    private final AntPathMatcher paths = new AntPathMatcher();
    private final SettingService settings;

    public ViewerGuard(SettingService settings) {
        this.settings = settings;
    }

    @Override
    public boolean preHandle(HttpServletRequest request, HttpServletResponse response, Object handler) {
        String method = request.getMethod();
        if (HttpMethod.GET.matches(method) || HttpMethod.HEAD.matches(method) || HttpMethod.OPTIONS.matches(method)) {
            return true;
        }
        String path = request.getRequestURI().substring(request.getContextPath().length());
        if (!paths.match(PATTERN, path) || LET_THROUGH.stream().anyMatch(p -> paths.match(p, path))) {
            return true;
        }
        String header = request.getHeader(SignedInUser.HEADER);
        if (header == null || header.isBlank()) {
            return true;
        }
        Map<String, String> vars = paths.extractUriTemplateVariables(PATTERN, path);
        String sheetId = URLDecoder.decode(vars.get("sheetId"), StandardCharsets.UTF_8).trim();
        if (settings.isViewer(sheetId, SignedInUser.decode(header))) {
            response.setStatus(HttpStatus.FORBIDDEN.value());
            return false;
        }
        return true;
    }
}
    public BulkVoidService(ClaimListOrder order, ClaimService service, RollupService rollups, SettingService settings,
            SheetService sheets) {
        this.order = order;
        this.service = service;
        this.rollups = rollups;
        this.settings = settings;
        this.sheets = sheets;
    }

    /** Void each selected claim that can be voided, in list order (people in the order they were
     *  added, each person's claims newest first), by exactly the rules of voiding one, with the reason
     *  given; each that cannot, or is not on the sheet, is refused and left as it is. Each claim is
     *  voided on its own, so a refused one writes nothing. */
    public Result voidAll(String sheetId, String user, Set<Long> ids, String reason) {
        List<Claim> voided = new ArrayList<>();
        if (settings.isViewer(sheetId, user) || sheets.isArchived(sheetId)) {
            // A viewer, or anyone on an archived sheet, changes nothing: every selected claim is refused.
            return new Result(voided, ids.size());
        }
        for (Claim claim : order.selected(sheetId, ids)) {
            try {
                voided.add(rollups.track(sheetId, user, () -> service.changeStatus(sheetId, user,
                        claim.getPersonId(), claim.getId(), ClaimStatus.VOID, reason)));
            } catch (VoidRefusedException | StatusChangeRefusedException | PermissionRefusedException
                    | PeriodClosedException | PersonRetiredException | ClaimLockedException
                    | NoSuchElementException refused) {
                // Left as it is: its change rolled back with its own transaction.
            }
        }
        return new Result(voided, ids.size() - voided.size());
    }
}

